const paginacao = createPagination({   // nav aria-label="Paginação"
  total: 10,                           // total de páginas
  current: 1,                          // página ativa, com aria-current="page"
  showPrevNext: true,                  // controles Anterior e Próxima
  align: 'start',
  onPageChange: (page) => irPara(page),
});
// As reticências entram sozinhas quando o total não cabe na régua.

extensibilityCode.react:
// O link é um <a> de verdade: as props do elemento passam direto.
// Para integrar com router, use o href do próprio roteador.
<PaginationLink
  href={`?page=${page}`}
  isActive={page === current}
  aria-label={`Ir para página ${page}`}
  onClick={(e) => { e.preventDefault(); irPara(page); }}
>
  {page}
</PaginationLink>

extensibilityCode.vanilla:
// A navegação não guarda estado: a página ativa é sempre a que você passa em
// `current`, e trocar de página significa recriar o elemento. O rótulo de cada
// link já sai com contexto ("Ir para página 3"), então não há o que anotar.
let atual = 1;

function remontar() {
  container.replaceChildren(
    createPagination({
      total: 10,
      current: atual,
      onPageChange: (page) => { atual = page; remontar(); },
    }),
  );
}

