extensibilityCode.vanilla:
// The navigation holds no state: the active page is always the one you pass in
// `current`, and changing pages means recreating the element. Every link ships
// with a contextual label ("Go to page 3"), so there is nothing to annotate.
let current = 1;

function remount() {
  container.replaceChildren(
    createPagination({
      total: 10,
      current,
      onPageChange: (page) => { current = page; remount(); },
    }),
  );
}

